// Markup safety, same as everywhere else that puts a name into SVG: a
// label is validated on registration, but this is the last gate before
// it lands inside somebody else's renderer.
func esc(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	return s
}

package nsview

import (
	"encoding/base64"
	"strings"
	"time"

	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/g1xr6tgxnpled50h74eafmvxway7z0ytr5rsmeme/nsdata/v2"
)

// The NFT artwork and every piece of display formatting live here, in a
// realm that can be redeployed, rather than in the vault that cannot.
// nsdata.TokenURI points at this realm through a settable prefix.

// TokenURI returns the full data: URI for a token, generated on every
// read so the image always reflects current state (never baked at mint).
func TokenURI(tid string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(BuildSVG(tid)))
}

// BuildSVG renders a token. Everything on the card derives from four
// stored values — owner, registered, expires, and the domain's drawing —
// so a renewal moves `expires` and the bar, the time remaining and the
// years held all follow from it. Nothing is baked at mint: the card is
// generated on every read, which is what lets a domain's artwork be
// changed after its names have been sold.
func BuildSVG(tid string) string {
	var registered, expires int64 // unix seconds
	var streak int64
	var frozen bool
	var domainLabel string

	if strings.HasPrefix(tid, "*") {
		label := tid[1:]
		if !nsdata.DomainExists(label) {
			return placeholderSVG("unknown")
		}
		_, registered, expires, streak, frozen = nsdata.GetDomainInfo(label)
		domainLabel = label
	} else {
		label, dom := splitTokenID(tid)
		if !nsdata.NameExists(label, dom) {
			return placeholderSVG("unknown")
		}
		_, registered, expires, streak, frozen, _ = nsdata.GetNameInfo(label, dom)
		domainLabel = dom
	}

	now := time.Now().Unix()
	// The three vault reads happen HERE, not inside cardSVG. That is what
	// leaves the card itself a pure function of its inputs, which is what
	// lets a test assert what a marketplace will show without standing up
	// a registry to do it.
	// A SKIN REPLACES THE CARD, so it is decided before anything is read
	// from the vault for drawing one. The ordinary path is untouched on
	// every other day of the year.
	if sk := skinFor(now); sk != "" && hasSkin(sk) {
		return skinSVG(sk, tid, now)
	}

	art := nsdata.GetDomainExtra(domainLabel, keyArt)
	return cardSVG(tid, art, registered, expires, streak, frozen, now, overlaySVG(now))
}

// cardSVG is the card itself, with every stored value already resolved.
// Split out from BuildSVG so the markup can be rendered — and asserted
// against — without a vault under it. TestStaticFrameShowsTheDate is the
// reason: what a marketplace shows as a still is a property of this
// string and of nothing else, and it deserves to be checked rather than
// assumed.
func cardSVG(tid, art string, registered, expires, streak int64, frozen bool, now int64, overlay string) string {
	accent := accentOf(art)
	status, edge := statusFields(expires, frozen)

	// The ribbon says something the rest of the card does not.
	// "DIAMOND HANDS" on a name minted this morning is a joke that lands
	// once; tied to tenure it is a thing you get TO.
	ribbon := status
	if status == "LIVE" {
		if streak >= 1 {
			ribbon = "DIAMOND HANDS"
		} else {
			ribbon = "FIRST YEAR"
		}
	}

	// The domain's drawing as a wash, centred: twelve cells at 26px is
	// 312 wide, so 44px of margin on every side.
	//
	// 0.07, not 0.12. At 0.12 a bright sprite competed with the name
	// sitting on top of it — the eye landed on the picture first and had
	// to hunt for the type. A wash should be felt rather than read.
	wash := spriteSVG(art, 26, 44, 44, "0.07")

	// The bar is the whole term, filled by how much of it is left.
	span := expires - registered
	if span < 1 {
		span = 1
	}
	left := expires - now
	if left < 0 {
		left = 0
	}
	if left > span {
		left = span
	}
	fill := (308 * left) / span

	heldLabel := "YEARS HELD"
	if streak == 1 {
		heldLabel = "YEAR HELD"
	}

	return ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400" role="img">
  <rect width="400" height="400" fill="#10101a"/>
  %s
  <rect x="12" y="12" width="376" height="376" rx="18" fill="none" stroke="%s" stroke-width="3"/>
  <text x="30" y="42" font-family="monospace" font-size="10" fill="%s" opacity="0.7">MINTED ON GNO.LAND</text>
  <text x="370" y="42" text-anchor="end" font-family="monospace" font-size="10" fill="%s" opacity="0.7">SINCE %s</text>
  <text x="200" y="196" text-anchor="middle" font-family="monospace" font-size="%d" font-weight="bold" fill="#ffffff">%s</text>
  <!-- THE STATIC FRAME. A marketplace showing this token as a still
       gets whichever of these two lines is visible with no animation
       running, and that MUST be the date. Everything that matters about
       a name at a glance -- is it live, is it expired, when does it go
       -- is in the date; "412 days left" frozen into a thumbnail is a
       number that was true once and is a lie thereafter.

       It works out that way under both kinds of renderer, which is why
       it is written like this and not any other way:

         a renderer that IGNORES SMIL uses the base attribute in the
         markup, so the date's opacity="1" and the counter's opacity="0"
         decide it

         a renderer that HONOURS SMIL and seeks to t=0 uses the first
         keyTime, so the date's values="1;0" and the counter's "0;1"
         decide it

       Both must keep agreeing. Reorder these two lines, or drop an
       explicit opacity, and the still becomes a countdown -- with
       nothing failing and nothing to notice until a card in somebody
       else's gallery says a name has 412 days left three years from
       now. Guarded by TestStaticFrameShowsTheDate. -->
  <text x="200" y="224" text-anchor="middle" font-family="monospace" font-size="13" fill="%s" opacity="1">%s<animate attributeName="opacity" calcMode="discrete" values="1;0" keyTimes="0;0.5" dur="8s" repeatCount="indefinite"/></text>
  <text x="200" y="224" text-anchor="middle" font-family="monospace" font-size="13" fill="%s" opacity="0">%s<animate attributeName="opacity" calcMode="discrete" values="0;1" keyTimes="0;0.5" dur="8s" repeatCount="indefinite"/></text>
  <rect x="46" y="256" width="308" height="9" rx="4" fill="#ffffff" opacity="0.13"/>
  <rect x="46" y="256" width="%d" height="9" rx="4" fill="%s"/>
  <text x="46" y="282" font-family="monospace" font-size="9" fill="#ffffff" opacity="0.45">%s</text>
  <text x="354" y="282" text-anchor="end" font-family="monospace" font-size="9" fill="#ffffff" opacity="0.45">%s</text>
  <text x="200" y="326" text-anchor="middle" font-family="monospace" font-size="30" font-weight="bold" fill="#ffffff">%d</text>
  <text x="200" y="344" text-anchor="middle" font-family="monospace" font-size="9" fill="%s" opacity="0.8">%s</text>
  <text x="200" y="372" text-anchor="middle" font-family="monospace" font-size="12" font-weight="bold" fill="%s">%s</text>
  %s
</svg>`,
		wash, edge,
		accent, accent, time.Unix(registered, 0).UTC().Format("2006"),
		fitSize(tid), escapeXML(tid),
		accent, time.Unix(expires, 0).UTC().Format("Jan 2, 2006"),
		accent, remaining(expires, now),
		fill, edge,
		time.Unix(registered, 0).UTC().Format("Jan 2006"),
		time.Unix(expires, 0).UTC().Format("Jan 2006"),
		streak, accent, heldLabel,
		edge, ribbon,
		overlay)
}

// fitSize solves for a size rather than stepping through a ladder.
// Monospace glyphs are ~0.6em, so a name up to the full 32-character
// limit sets on one line without overflowing 336px.
func fitSize(s string) int {
	n := len(s)
	if n < 1 {
		n = 1
	}
	size := 336 * 10 / (6 * n)
	// 40, not 34: the name is the thing somebody bought, and on a card
	// where the drawing sits behind it, the type has to be the loudest
	// object on the tile. Short names were leaving the middle of the card
	// half empty.
	if size > 40 {
		size = 40
	}
	if size < 11 {
		size = 11
	}
	return size
}

// domainAccent reads the accent out of the domain's stored drawing, so
// the card wears the domain's own colour without this realm carrying a
// palette of its own. Falls back to the house colour.
func domainAccent(domainLabel string) string {
	return accentOf(nsdata.GetDomainExtra(domainLabel, keyArt))
}

func accentOf(enc string) string {
	if len(enc) >= 8 && enc[1] == '#' && isHexColour(enc[1:8]) {
		return enc[1:8]
	}
	return "#5eead4"
}

func remaining(expires, now int64) string {
	if now >= expires {
		d := (now - expires) / daySeconds
		if d <= 0 {
			return "expired today"
		}
		if d == 1 {
			return "1 day past due"
		}
		return ufmt.Sprintf("%d days past due", d)
	}
	d := (expires - now) / daySeconds
	if d <= 0 {
		return "expires today"
	}
	if d == 1 {
		return "1 day remaining"
	}
	return ufmt.Sprintf("%d days remaining", d)
}

// keyArt is the per-domain extension key holding the drawing. The value
// is "A#facc15,B#7c2d12|............|....AAAA....|..." — the palette,
// then twelve rows of twelve characters where '.' is transparent.
//
// PARSED DEFENSIVELY AND NEVER TRUSTED. It is written by whichever logic
// realm is current, so a future one could store something malformed;
// anything unexpected yields no sprite rather than broken markup inside
// a token that a marketplace will render.
const keyArt = "art"

func spriteSVG(enc string, px, ox, oy int, opacity string) string {
	if enc == "" {
		return ""
	}
	parts := strings.Split(enc, "|")
	if len(parts) != 13 {
		return ""
	}
	// palette: "A#facc15,B#7c2d12"
	colours := map[string]string{}
	for _, entry := range strings.Split(parts[0], ",") {
		// key + "#" + six hex digits: "A#facc15" is EIGHT characters.
		// This read 7 and rejected every valid sprite; the test caught it.
		if len(entry) != 8 || entry[1] != '#' {
			return ""
		}
		key := entry[:1]
		hex := entry[1:]
		if !isHexColour(hex) {
			return ""
		}
		colours[key] = hex
	}
	var b strings.Builder
	for y := 1; y <= 12; y++ {
		row := parts[y]
		if len(row) != 12 {
			return ""
		}
		for x := 0; x < 12; x++ {
			ch := row[x : x+1]
			if ch == "." {
				continue
			}
			c, ok := colours[ch]
			if !ok {
				return ""
			}
			b.WriteString(ufmt.Sprintf(
				`<rect x="%d" y="%d" width="%d" height="%d" fill="%s"/>`,
				ox+(x*px), oy+((y-1)*px), px, px, c))
		}
	}
	if b.Len() == 0 {
		return ""
	}
	return `<g opacity="` + opacity + `">` + b.String() + `</g>`
}

func isHexColour(s string) bool {
	if len(s) != 7 || s[0] != '#' {
		return false
	}
	for i := 1; i < 7; i++ {
		c := s[i]
		if !(c >= '0' && c <= '9') && !(c >= 'a' && c <= 'f') && !(c >= 'A' && c <= 'F') {
			return false
		}
	}
	return true
}

func placeholderSVG(msg string) string {
	return ufmt.Sprintf(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 400">`+
		`<rect width="400" height="400" fill="#10101a"/>`+
		`<text x="200" y="200" text-anchor="middle" font-family="monospace" font-size="18" fill="#666680">%s</text></svg>`,
		escapeXML(msg))
}

// statusFields formats a lifecycle state for display. Reads the grace
// period from nsdata rather than hardcoding it, so retuning the lifecycle
// is a config change and this stays correct.
// All lifecycle times are unix seconds, so this is integer arithmetic
// over a day constant rather than duration division.
const daySeconds = int64(24 * 60 * 60)

func statusFields(expires int64, frozen bool) (status, edge string) {
	if frozen {
		return "FROZEN", "#8888aa"
	}
	now := time.Now().Unix()
	grace := nsdata.GetGracePeriod()
	switch {
	case now < expires:
		return "LIVE", "#4ade80"
	case now < expires+grace:
		return "GRACE PERIOD", "#facc15"
	default:
		return "LAPSED", "#f87171"
	}
}

func escapeXML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	return s
}

// Package nftlimits stores an optional "max tokens per wallet" cap for
// collections minted through gno.land/r/hazen/nft, as a separate realm
// for the same reason nftoffers is separate: gno.land packages are
// immutable once deployed, and nft.gno was already live with real
// collections, so there is no in-place way to add a new field to its
// Collection struct or a new check to its Mint function.
//
// IMPORTANT — this is an advisory / frontend-enforced cap, not a
// trustless one. nft.Mint itself has no knowledge of this realm and
// does not consult it, so nothing on-chain stops a caller from
// bypassing the limit by calling nft.Mint directly (e.g. via gnokey)
// instead of going through the gnoNFT frontend. True trustless
// enforcement would require the check to live inside nft.gno's own
// Mint function, which can't be retrofitted onto the already-deployed
// realm. This is still useful for the normal case (everyone mints
// through the dApp UI) and is the best available option without
// forking the whole nft/nftmarket/nftoffers realm family onto a new,
// mutually-incompatible v2 path.
package nftlimits

import (
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft"
)

// limits maps collectionID -> int64 (max tokens per wallet). Absence
// from the tree means "no limit configured" (unlimited), same
// convention nft.gno uses for maxSupply/publicMint.
var limits = avl.NewTree()

// SetMaxPerWallet sets (or clears, with max == 0) the per-wallet mint
// cap for a collection. Only the collection's creator (per
// nft.GetCollection) may call this.
func SetMaxPerWallet(cur realm, collectionID string, max int64) {
	caller := unsafe.OriginCaller()

	c := nft.GetCollection(collectionID) // panics if the collection doesn't exist
	if c.Creator != caller {
		panic("only the collection's creator can set its mint limit")
	}
	if max < 0 {
		panic("max must be >= 0 (0 clears the limit)")
	}

	if max == 0 {
		limits.Remove(collectionID)
		return
	}
	limits.Set(collectionID, max)
}

// GetMaxPerWallet returns the configured per-wallet cap for a
// collection, or 0 if none is set (unlimited).
func GetMaxPerWallet(collectionID string) int64 {
	v := limits.Get(collectionID)
	if v == nil {
		return 0
	}
	return v.(int64)
}

// Render implements the gno.land realm home-page convention.
func Render(path string) string {
	if path != "" {
		max := GetMaxPerWallet(path)
		if max == 0 {
			return "# collection " + path + "\n\nno per-wallet mint limit configured.\n"
		}
		return "# collection " + path + "\n\nmax " + strconv.FormatInt(max, 10) + " token(s) per wallet.\n"
	}

	out := "# Hazen NFT Mint Limits\n\n"
	hasAny := false
	limits.Iterate("", "", func(key string, value any) bool {
		hasAny = true
		out += "- collection " + key + ": max " + strconv.FormatInt(value.(int64), 10) + " per wallet\n"
		return false
	})
	if !hasAny {
		out += "No collections have a configured mint limit.\n"
	}
	return out
}

package nftlimits

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft"
)

func TestSetAndGetMaxPerWallet(cur realm, t *testing.T) {
	alice := testutils.TestAddress("lim-alice")

	var collID string
	t.Run("alice creates a collection and sets a limit", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		collID = nft.CreateCollection(cross(cur), "Limit Test", "LIM", "", "", 100, 0, true)

		uassert.Equal(t, int64(0), GetMaxPerWallet(collID))

		SetMaxPerWallet(cross(cur), collID, 2)
		uassert.Equal(t, int64(2), GetMaxPerWallet(collID))
	})

	t.Run("alice clears the limit", func(t *testing.T) {
		SetMaxPerWallet(cross(cur), collID, 0)
		uassert.Equal(t, int64(0), GetMaxPerWallet(collID))
	})
}

func TestOnlyCreatorCanSetLimit(cur realm, t *testing.T) {
	alice := testutils.TestAddress("lim-alice2")
	bob := testutils.TestAddress("lim-bob2")

	testing.SetOriginCaller(alice)
	collID := nft.CreateCollection(cross(cur), "Limit Test 2", "LIM2", "", "", 100, 0, true)

	testing.SetOriginCaller(bob)
	uassert.AbortsWithMessage(t, cur, "only the collection's creator can set its mint limit", func() {
		SetMaxPerWallet(cross(cur), collID, 1)
	})
}

func TestNegativeLimitAborts(cur realm, t *testing.T) {
	alice := testutils.TestAddress("lim-alice3")

	testing.SetOriginCaller(alice)
	collID := nft.CreateCollection(cross(cur), "Limit Test 3", "LIM3", "", "", 100, 0, true)

	uassert.AbortsWithMessage(t, cur, "max must be >= 0 (0 clears the limit)", func() {
		SetMaxPerWallet(cross(cur), collID, -1)
	})
}

// Package nftprofiles lets any address set a lightweight, self-service
// profile (display name + avatar image URI) shown across the gnoNFT
// frontend wherever that address would otherwise just be a raw
// g1... string with a generated color+initials avatar
// (components/Avatar.tsx). Separate realm rather than bolting onto
// nft.gno/nftmarket.gno/nftoffers.gno/nftlimits.gno for the same
// immutability reason all of those already are: each is independently
// deployed and none of them has any notion of "user profile".
//
// Fully self-service and permissionless: anyone can set their own
// profile for their own address (unsafe.OriginCaller()), there's no
// registration/approval step. Cosmetic only — this has no bearing on
// any other realm's authorization logic (ownership/creator checks
// everywhere else still key off the raw address, never off this
// display name).
package nftprofiles

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// MaxDisplayNameLen and MaxAvatarURILen keep storage costs bounded and
// prevent this from being used as generic blob storage.
const (
	MaxDisplayNameLen = 32
	MaxAvatarURILen   = 256
)

// Profile is one address's self-set profile.
type Profile struct {
	address     address
	displayName string
	avatarURI   string
	updatedAt   int64
}

// ProfileInfo is the exported, read-only view of a Profile.
type ProfileInfo struct {
	Address     address
	DisplayName string
	AvatarURI   string
	UpdatedAt   int64
}

var profiles = avl.NewTree() // address.String() -> *Profile

// SetProfile sets (or updates) the caller's own display name and/or
// avatar URI. Pass an empty string for either field to clear just that
// field while keeping the other. Calling with both empty removes the
// profile entirely (reverting the address to the frontend's generated
// fallback avatar).
func SetProfile(cur realm, displayName, avatarURI string) {
	caller := unsafe.OriginCaller()

	if len(displayName) > MaxDisplayNameLen {
		panic("display name too long (max " + strconv.Itoa(MaxDisplayNameLen) + " chars)")
	}
	if len(avatarURI) > MaxAvatarURILen {
		panic("avatar URI too long (max " + strconv.Itoa(MaxAvatarURILen) + " chars)")
	}

	key := caller.String()
	if displayName == "" && avatarURI == "" {
		profiles.Remove(key)
		return
	}

	profiles.Set(key, &Profile{
		address:     caller,
		displayName: displayName,
		avatarURI:   avatarURI,
		updatedAt:   runtime.ChainHeight(),
	})
}

// GetProfile returns the profile for an address, or a zero-value
// ProfileInfo (empty DisplayName/AvatarURI, UpdatedAt == 0) if none was
// ever set — callers should treat that as "use the generated fallback".
func GetProfile(addr address) ProfileInfo {
	v := profiles.Get(addr.String())
	if v == nil {
		return ProfileInfo{Address: addr}
	}
	return toInfo(v.(*Profile))
}

// Render implements the gno.land realm home-page convention. Path, if
// given, is the bech32 address to look up (mirrors the other realms'
// single-path-segment convention).
func Render(path string) string {
	if path != "" {
		info := GetProfile(address(path))
		if info.DisplayName == "" && info.AvatarURI == "" {
			return "# " + path + "\n\nno profile set.\n"
		}
		return "# " + path + "\n\n- Display name: " + info.DisplayName + "\n- Avatar: " + info.AvatarURI + "\n"
	}

	out := "# Hazen NFT Profiles\n\n"
	hasAny := false
	profiles.Iterate("", "", func(key string, value any) bool {
		hasAny = true
		p := value.(*Profile)
		out += "- " + key + ": " + p.displayName + "\n"
		return false
	})
	if !hasAny {
		out += "No profiles set yet.\n"
	}
	return out
}

func toInfo(p *Profile) ProfileInfo {
	return ProfileInfo{
		Address:     p.address,
		DisplayName: p.displayName,
		AvatarURI:   p.avatarURI,
		UpdatedAt:   p.updatedAt,
	}
}

package nftprofiles

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestSetAndGetProfile(cur realm, t *testing.T) {
	alice := testutils.TestAddress("prof-alice")

	t.Run("no profile initially", func(t *testing.T) {
		info := GetProfile(alice)
		uassert.Equal(t, "", info.DisplayName)
		uassert.Equal(t, "", info.AvatarURI)
	})

	t.Run("alice sets her profile", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		SetProfile(cross(cur), "Alice", "ipfs://bafy.../avatar.png")

		info := GetProfile(alice)
		uassert.Equal(t, "Alice", info.DisplayName)
		uassert.Equal(t, "ipfs://bafy.../avatar.png", info.AvatarURI)
	})

	t.Run("alice clears her profile", func(t *testing.T) {
		testing.SetOriginCaller(alice)
		SetProfile(cross(cur), "", "")

		info := GetProfile(alice)
		uassert.Equal(t, "", info.DisplayName)
		uassert.Equal(t, "", info.AvatarURI)
	})
}

func TestDisplayNameTooLong(cur realm, t *testing.T) {
	alice := testutils.TestAddress("prof-alice2")
	testing.SetOriginCaller(alice)

	tooLong := strings.Repeat("x", MaxDisplayNameLen+1)
	uassert.AbortsWithMessage(t, cur, "display name too long (max 32 chars)", func() {
		SetProfile(cross(cur), tooLong, "")
	})
}

func TestOnlyAffectsOwnAddress(cur realm, t *testing.T) {
	alice := testutils.TestAddress("prof-alice3")
	bob := testutils.TestAddress("prof-bob3")

	testing.SetOriginCaller(alice)
	SetProfile(cross(cur), "Alice", "")

	uassert.Equal(t, "", GetProfile(bob).DisplayName)
}
